/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
# print dark intervals per row, interior x 50..1230, runs >=5
for y in range(150,501,10):
 m=g[y]<50
 d=np.diff(np.pad(m.astype(int),(1,1)))
 runs=[]
 for a,b in zip(np.where(d==1)[0],np.where(d==-1)[0]):
  if b-a>=5:runs.append((a,b-1,round(float(g[y,a:b].mean()),1)))
 if runs: print(y,runs)
PY"
